using DbdPresence.Core.Detection;
using DbdPresence.Vision.Imaging;

namespace DbdPresence.Vision.Evaluation;

/// <summary>Where the evaluated frames came from. Only <see cref="Real"/> data can say anything about accuracy.</summary>
public enum DataOrigin
{
    /// <summary>Generated by code. Proves mechanics only; never reported as accuracy.</summary>
    Synthetic,

    /// <summary>Recorded from the real game by the owner, on a held-out split.</summary>
    Real,

    /// <summary>
    /// Recorded from the real game but taken from the tuning split. It is the data the thresholds are calibrated on, so its numbers say nothing about
    /// accuracy and can never earn a tier (DETECTION_VALIDATION §5).
    /// </summary>
    Tuning,
}

/// <summary>One sampled frame of a unit.</summary>
/// <param name="TimestampUtc">When the frame was sampled.</param>
/// <param name="Image">The frame (or the frame's relevant area).</param>
public sealed record EvaluationFrame(DateTimeOffset TimestampUtc, ImageBuffer Image);

/// <summary>
/// One gate unit: a trial, or a scene segment (DETECTION_VALIDATION §1.4). Frames inside a unit are clustered, never independent,
/// so every count in a report is a count of units.
/// </summary>
/// <param name="UnitId">Unit id, unique within the set.</param>
/// <param name="SessionId">The recording session the unit belongs to.</param>
/// <param name="TruthLabel">The ground truth, or null when it was not legible on screen (the unit is then excluded from precision and recall).</param>
/// <param name="Frames">The unit's frames in time order.</param>
public sealed record EvaluationUnit(string UnitId, string SessionId, string? TruthLabel, IEnumerable<EvaluationFrame> Frames);

/// <summary>What a classifier read from one frame.</summary>
/// <param name="Label">The label, or null when it abstained (unreadable).</param>
/// <param name="Score">The raw score.</param>
public readonly record struct FramePrediction(string? Label, double Score);

/// <summary>Reads one frame. A detector adapter and a scripted classifier both fit.</summary>
public delegate FramePrediction FrameClassifier(EvaluationFrame frame);

/// <summary>Everything that identifies an evaluation run. Reports contain no timestamps so they reproduce bit for bit.</summary>
/// <param name="DatasetId">The labelled set.</param>
/// <param name="Detector">The detector name.</param>
/// <param name="DetectorVersion">The detector version.</param>
/// <param name="Context">The context the units come from (HUD profile, resolution class, language, game version).</param>
/// <param name="Origin">Synthetic or real data.</param>
/// <param name="Rule">The confirmation rule applied to each unit's frames (same code as the engine).</param>
public sealed record EvaluationOptions(string DatasetId, string Detector, int DetectorVersion, string Context, DataOrigin Origin, ConfirmationRule Rule);

/// <summary>A count out of a total with its Wilson interval.</summary>
/// <param name="Successes">The numerator.</param>
/// <param name="Trials">The denominator.</param>
public sealed record Proportion(int Successes, int Trials)
{
    /// <summary>Gets the ratio, or null (UNKNOWN) when there are no trials.</summary>
    public double? Value => Trials == 0 ? null : (double)Successes / Trials;

    /// <summary>Gets the two-sided 95% Wilson interval, or null (UNKNOWN) when there are no trials.</summary>
    public Interval? Wilson => Trials == 0 ? null : WilsonInterval.TwoSided95(Successes, Trials);
}

/// <summary>Per-class metrics. A class that is always wrong cannot hide inside a pooled score.</summary>
/// <param name="Label">The class.</param>
/// <param name="TruthUnits">Units whose truth is this class.</param>
/// <param name="ConfirmedAsClass">Units where this class was confirmed (rightly or wrongly).</param>
/// <param name="TruePositives">Units with truth = class and the class confirmed.</param>
/// <param name="FalsePositives">Units with truth ≠ class where the class was confirmed.</param>
/// <param name="Abstained">Units with truth = class where nothing was confirmed.</param>
/// <param name="Precision">TP out of units confirmed as the class.</param>
/// <param name="Recall">TP out of units with truth = class.</param>
/// <param name="FalsePositiveRate">FP out of units with truth ≠ class.</param>
/// <param name="Publishable">Per-class rule: at least 10 units with truth = class and 0 false positives.</param>
public sealed record ClassMetrics(
    string Label,
    int TruthUnits,
    int ConfirmedAsClass,
    int TruePositives,
    int FalsePositives,
    int Abstained,
    Proportion Precision,
    Proportion Recall,
    Proportion FalsePositiveRate,
    bool Publishable);

/// <summary>Confusion matrix over the legible units. Rows are the truth; columns are the confirmed class plus a final abstain column.</summary>
/// <param name="Classes">Class labels in ordinal order. The last column of every row is "abstain".</param>
/// <param name="Counts">Counts[truth][predicted]; the predicted index equals <c>Classes.Count</c> for abstain.</param>
public sealed record ConfusionMatrix(IReadOnlyList<string> Classes, IReadOnlyList<IReadOnlyList<int>> Counts);

/// <summary>What the measured gates of DETECTION_VALIDATION §7 say. Gates that need other evidence are listed as not assessed.</summary>
/// <param name="Applicable">False for synthetic data: no tier can be earned from it.</param>
/// <param name="ExperimentalMeasuredGatesMet">≥ 30 units, ≥ 5 sessions, 0 errors, coverage ≥ 50%.</param>
/// <param name="ValidatedMeasuredGatesMet">Precision lower bound ≥ 99%, ≥ 10 sessions, coverage ≥ 80%.</param>
/// <param name="Notes">Why a gate is or is not met.</param>
/// <param name="NotAssessed">Gates this report cannot assess (stale duration, per-class latency, RPC replay, class rules per vocabulary).</param>
public sealed record GateAssessment(bool Applicable, bool ExperimentalMeasuredGatesMet, bool ValidatedMeasuredGatesMet, IReadOnlyList<string> Notes, IReadOnlyList<string> NotAssessed);

/// <summary>The metrics report (DETECTION_VALIDATION §6). Values that cannot be computed are null and render as UNKNOWN.</summary>
public sealed record EvaluationReport
{
    /// <summary>Gets the run identity.</summary>
    public required EvaluationOptions Options { get; init; }

    /// <summary>Gets the number of units supplied.</summary>
    public required int Units { get; init; }

    /// <summary>Gets the units with legible ground truth (the denominator of recall and coverage).</summary>
    public required int LegibleUnits { get; init; }

    /// <summary>Gets the units without legible truth where a value was nevertheless confirmed; they are never counted as correct.</summary>
    public required int ConfirmedWithoutTruth { get; init; }

    /// <summary>Gets the distinct recording sessions among the legible units.</summary>
    public required int Sessions { get; init; }

    /// <summary>Gets the legible units where a value was confirmed.</summary>
    public required int Confirmed { get; init; }

    /// <summary>Gets the confirmed units whose confirmed values were all correct.</summary>
    public required int Correct { get; init; }

    /// <summary>Gets the legible units where nothing was confirmed.</summary>
    public required int Abstained { get; init; }

    /// <summary>Gets precision of published values: correct units out of confirmed units.</summary>
    public required Proportion Precision { get; init; }

    /// <summary>Gets coverage (recall): correct units out of legible units.</summary>
    public required Proportion Coverage { get; init; }

    /// <summary>Gets the abstention rate: abstained units out of legible units.</summary>
    public required Proportion AbstentionRate { get; init; }

    /// <summary>Gets the per-class metrics in ordinal label order.</summary>
    public required IReadOnlyList<ClassMetrics> Classes { get; init; }

    /// <summary>Gets the confusion matrix.</summary>
    public required ConfusionMatrix Confusion { get; init; }

    /// <summary>Gets the median seconds from a unit's first frame to the confirmation of the correct value, or null.</summary>
    public required double? MedianSecondsToDetect { get; init; }

    /// <summary>Gets the 95th percentile (nearest rank) of seconds to detect, or null.</summary>
    public required double? P95SecondsToDetect { get; init; }

    /// <summary>Gets the gate assessment.</summary>
    public required GateAssessment Gates { get; init; }
}
